{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Stavudine, a nucleoside analogue with high assay transfer, was reported to have high oral bioavailability in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Nipradilol absolute oral bioavailability was 0.43 ± 0.04 in older subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "(-)-Praziquantel oral bioavailability was 27.2 ± 5.4% even in patients with hepatic cirrhosis, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Vinorelbine, a large complex alkaloid, had absolute oral bioavailability of 36 ± 10% in patients, supporting high F despite high molecular complexity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Maraviroc absolute oral bioavailability was 33% at a 300 mg dose, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Naldemedine estimated absolute oral bioavailability was 20–56%, with the lower bound at the threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Glasdegib absolute oral bioavailability was 77.12% in healthy volunteers, strongly above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues show oral bioavailability at or above 20%, many substantially above; the mixed physicochemical prior is outweighed by consistent experimental evidence, so the query is predicted high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "Query-specific metabolism, efflux, and solubility behavior are not experimentally characterized.",
    "The query's high molecular weight and TPSA may introduce absorption variability not fully captured by the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

